import { MakeLogicType, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { dayjs } from 'lib/dayjs'
import { projectLogic } from 'scenes/projectLogic'

import { transactionalPushLogStatsRetrieve } from 'products/messaging/frontend/generated/api'
import type { TransactionalPushStatsRowApi } from 'products/messaging/frontend/generated/api.schemas'

import { transactionalEmailMetricsLogic } from './transactionalEmailMetricsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalPushMetricsLogicValues {
    currentProjectId: number | null // projectLogic
    hours: number // transactionalEmailMetricsLogic
    pushStats: TransactionalPushStatsRowApi[] | null
    pushStatsFailed: boolean
    pushStatsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalPushMetricsLogicActions {
    setHours: (hours: number) => {
        hours: number
    } // transactionalEmailMetricsLogic
    loadPushStats: (_: void) => void
    loadPushStatsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPushStatsSuccess: (
        pushStats: TransactionalPushStatsRowApi[] | null,
        payload?: void
    ) => {
        pushStats: TransactionalPushStatsRowApi[] | null
        payload?: void
    }
}

export type transactionalPushMetricsLogicType = MakeLogicType<
    transactionalPushMetricsLogicValues,
    transactionalPushMetricsLogicActions
>

/** Push sends per push notification on the Metrics tab, over the period the email metrics show. */
export const transactionalPushMetricsLogic = kea<transactionalPushMetricsLogicType>([
    path(['products', 'workflows', 'frontend', 'Transactional', 'metrics', 'transactionalPushMetricsLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId'], transactionalEmailMetricsLogic, ['hours']],
        actions: [transactionalEmailMetricsLogic, ['setHours']],
    })),
    reducers({
        pushStatsFailed: [
            false,
            {
                loadPushStats: () => false,
                loadPushStatsSuccess: () => false,
                loadPushStatsFailure: () => true,
            },
        ],
    }),
    loaders(({ values }) => ({
        pushStats: [
            null as TransactionalPushStatsRowApi[] | null,
            {
                loadPushStats: async (_: void, breakpoint) => {
                    if (values.currentProjectId === null) {
                        return null
                    }
                    try {
                        const response = await transactionalPushLogStatsRetrieve(String(values.currentProjectId), {
                            date_from: dayjs().subtract(values.hours, 'hour').toISOString(),
                        })
                        return [...response.results]
                    } finally {
                        // A superseded request, failed or not, must not replace newer numbers.
                        breakpoint()
                    }
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        setHours: () => actions.loadPushStats(),
    })),
    afterMount(({ actions }) => {
        actions.loadPushStats()
    }),
])
